'use client';

import { useId, type CSSProperties, type ReactNode } from 'react';
import './bento-grid.css';

export type BentoGridItem = {
  id: string;
  title: string;
  description?: ReactNode;
  icon?: ReactNode;
  /** Caller-provided visual or module content; never synthesized data. */
  header?: ReactNode;
  content?: ReactNode;
  columnSpan?: 1 | 2 | 3;
  rowSpan?: 1 | 2;
  action?: { label: string; onAction: () => void; disabled?: boolean };
};
export type BentoGridProps = {
  items: readonly BentoGridItem[];
  label: string;
  columns?: 2 | 3;
  selectedId?: string | null;
  className?: string;
};

/** Explicit content-driven modules inspired by Aceternity's Bento Grid. */
export function BentoGrid({ items, label, columns = 3, selectedId = null, className = '' }: BentoGridProps) {
  const uid = useId();
  return <section className={`mf-bento ${className}`} aria-label={label} data-columns={columns}>
    {items.map(item => <article key={item.id} className="mf-bento__item"
      aria-labelledby={`${uid}-${item.id}`} data-selected={selectedId === item.id || undefined}
      data-column-span={Math.min(item.columnSpan ?? 1, columns)}
      style={{ '--mf-bento-columns': Math.min(item.columnSpan ?? 1, columns), '--mf-bento-rows': item.rowSpan ?? 1 } as CSSProperties}>
      {item.header && <div className="mf-bento__header">{item.header}</div>}
      <div className="mf-bento__body">
        {item.icon && <span className="mf-bento__icon" aria-hidden="true">{item.icon}</span>}
        <h3 id={`${uid}-${item.id}`}>{item.title}</h3>
        {item.description && <div className="mf-bento__description">{item.description}</div>}
        {item.content && <div className="mf-bento__content">{item.content}</div>}
        {item.action && <button className="mf-bento__action" type="button" disabled={item.action.disabled}
          onClick={item.action.onAction}>{item.action.label}<svg aria-hidden="true" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M4 10h11m-4-4 4 4-4 4"/></svg></button>}
      </div>
    </article>)}
  </section>;
}

/* Public default preview: neutral-600 text, neutral-500 icons, neutral-200 edges. */
.mf-bento{--mf-bento-text:oklch(0.439 0 0);--mf-bento-icon:oklch(0.556 0 0);--mf-bento-border:oklch(0.922 0 0)}
.mf-bento{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-auto-rows:minmax(248px,auto);gap:16px;width:100%;color:var(--mf-bento-text);font:14px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}
.mf-bento[data-columns="2"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-bento *{box-sizing:border-box}
.mf-bento__item{grid-column:span var(--mf-bento-columns,1);grid-row:span var(--mf-bento-rows,1);min-width:0;padding:20px;border:1px solid var(--mf-bento-border);border-radius:16px;background:#fff;box-shadow:0 2px 3px -1px #0000001a,0 1px #191c2105,0 0 0 1px #191c2114;display:flex;flex-direction:column;gap:18px;transition:background-color .2s,border-color .2s,box-shadow .2s cubic-bezier(.4,0,.2,1)}
.mf-bento__item:hover,.mf-bento__item:focus-within{box-shadow:0 20px 25px -5px #0000001a,0 8px 10px -6px #0000001a}
.mf-bento__item[data-selected]{background:oklch(0.97 0 0);border-color:var(--mf-bento-icon)}
.mf-bento__item[data-selected]:hover{background:oklch(0.922 0 0)}
.mf-bento__header{position:relative;display:flex;align-items:center;justify-content:center;min-height:106px;flex:1;border-radius:11px;background:linear-gradient(to bottom right,oklch(0.922 0 0),oklch(0.97 0 0));overflow:hidden}
.mf-bento__body{transition:transform .2s cubic-bezier(.4,0,.2,1);padding-right:8px}
.mf-bento__item:hover .mf-bento__body,.mf-bento__item:focus-within .mf-bento__body{transform:translateX(8px)}
.mf-bento__icon{display:flex;width:20px;height:20px;color:var(--mf-bento-icon);margin-bottom:9px}
.mf-bento__icon svg{width:100%;height:100%}
.mf-bento__body h3{margin:0 0 5px;font-size:14px;font-weight:600;letter-spacing:-.25px;overflow-wrap:anywhere}
.mf-bento__description{color:var(--mf-bento-text);font-size:12px;line-height:1.6}
.mf-bento__content{margin-top:12px}
.mf-bento__action{appearance:none;display:flex;align-items:center;gap:7px;margin-top:14px;border:1px solid #d4d4d4;border-radius:7px;background:#fff;color:var(--mf-bento-text);padding:6px 9px;font:500 11px/1.4 inherit;font-family:inherit;font-size:11px;cursor:pointer;transition:background .15s}
.mf-bento__action svg{width:15px;height:15px}
.mf-bento__action:hover:not(:disabled){background:oklch(0.97 0 0)}
.mf-bento__action:disabled{opacity:.65;cursor:not-allowed}
.mf-bento__action:focus-visible{outline:3px solid var(--mf-bento-text);outline-offset:3px}
@media(max-width:800px){.mf-bento{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-bento__item[data-column-span="3"]{grid-column:span 2}
}
@media(max-width:560px){.mf-bento,.mf-bento[data-columns="2"]{grid-template-columns:minmax(0,1fr);grid-auto-rows:auto;gap:12px}
.mf-bento__item,.mf-bento__item[data-column-span="3"]{grid-column:span 1;grid-row:span 1;min-height:230px}
.mf-bento__header{min-height:124px}
}
@media(prefers-reduced-motion:reduce){.mf-bento__item,.mf-bento__body,.mf-bento__action{transition:none}
.mf-bento__item:hover .mf-bento__body,.mf-bento__item:focus-within .mf-bento__body{transform:none}
}
